with unpacked as (select id, currency, tier_limits, tier_prices, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps from price_tiers) select id, currency, avg_tier_price, first_value(avg_tier_price, true) over (order by avg_tier_price, id rows between unbounded preceding and current row) as first_known_avg_tier_price, sum(avg_tier_price) over (order by avg_tier_price, id rows between unbounded preceding and current row) as cumulative_avg_tier_price, row_number() over (partition by currency order by avg_tier_price desc, id) as event_seq from unpacked
